    workDesc: 'باؤنٹی ہنٹنگ ڈے ہب کا بیلٹ ان ٹاسک اور انعام سسٹم ہے، نہ کہ تیسرے طرف کے فری لانس مارکیٹ پلیس۔ ایکوسسٹم میں کوئی بھی شخص باؤنٹی پوسٹ کر سکتا ہے اور کوئی بھی ہنٹر بن کر اسے دھمک دے سکتا ہے، انعام ایسی ہی سیکیورٹی میں رکھا جاتا ہے جب تک کام مکمل نہ ہو جائے۔ یہ کام اور انگیزیٹمنٹ کو پلتفرم کا ایک نیٹوو پارٹ بناتا ہے: باؤنٹی پوسٹ کرنے والے لوگ، کام مکمل کرنے والے ہنٹرز اور ان ٹوکنز جو ان سب کو سٹل کرتے ہیں، سب ڈے ہب میں ہی رہتے ہیں۔ باؤنٹی ڈے ہب ٹوکنز یا یو ایس ڈی سی میں ادا کیے جاتے ہیں۔',
