    workB1Desc: 'کسی بھی شخص نیا باؤنٹی پوسٹ کر سکتا ہے، جس میں ایک صاف اور واضح بریف اور انعام ڈے ہب ٹوکنز یا یو ایس سی سی میں ہو، یہ ہو یا کام کا ایک ٹکڑا جو ڈلیوری کرنے کے لیے ہو یا انگیجمنٹ ٹاسک جیسے کہ شیرنگ، کلپنگ یا کنٹینٹ پرو موٹنگ۔',
    workB2Desc: 'بھینچے کھول کر دکھاوے، قیمتیں یا سکہ پر فیلٹر کرے، جو چاہے اُسی کو دھڑکاوے، اور پریمیوم لگانے کے لیے اپنا کام سابمٹ کرے۔ ہر کاربری کو ہنٹر بننے کا حق ہے، کوئی اپلیکیشن یا گیت کیپنگ نہیں چاہیے۔',
    workB3: 'بانتیاں کی کٹیگریاں:',
    workB4: 'اسکرو پروٹیکشن:',
    workB4Desc: 'ہر انعام کو جب کوئی باؤنٹی پوسٹ کی جاتی ہے، وہ اسکراؤ میں رکھ دیا جاتا ہے، اور صرف جب کام قبول کر لیا جاتا ہے تو ہنٹر کو ریلیز کیا جاتا ہے، دونوں طرف کی حفاظت کے لیے۔',
    workB5Desc: 'کریٹرز اپنا کامنٹی کبھرتے ہوئے باؤنٹی پوسٹ کرتی ہیں، اور ڈیہب کامنٹی باؤنٹی پوسٹ کرکے اپنا خود ترویج کرتی ہے اور اکوسسٹم کو بڑھاتی ہے، ترویج کو ایک انعام یافتہ، ٹریک کرنے والا کام بناتی ہے۔',
    workB6Desc: 'ایک مخصوصی تنازعہ کی پروسیس، ڈلیوری پر اختلافات کو حل کرتی ہے، اس لیے اسکراؤ ایوارڈز ہمیشہ انصاف سے حل ہوتے ہیں۔',
    storesTitle: 'دُکَانیں',
    storesDesc: 'دُکَانوں نِی کِریئٹرز اوَ بِزنسز کو دِیہوب مِن دِی نَیٹیو دُکَان کھُولنے دے اَواز دِیتے ہَیں، اوَ اُنہیں اُن کے دُوڑے (اوڈینس) کو ڈِیریکٹ سِل کرنے دے اَواز دِیتے ہَیں، جو دِیہوب ٹوکنز مِن دِی سِٹل ہُو جاتے ہَیں۔ ایک دُکَان اپنا اَپنا پیج پر رِہتی ہَے، کِریئٹرز کی کِنتِنت کے سَامنے بِٹھتی ہَے، اوَ فالوورز کو کُستومرز بَنانے کِی سَہولیت دِیتے ہَے، بِگَہِی اُنہیں اِکٹیرنل چِکآؤٹ پر رِڈِریکٹ نَہیں کِیا جَاتا۔ کیونکہ پِیمنٹ اَپ کے اِسے بِلٹ-ان وَلِٹ سے گُزرتا ہَے، بائِیرز کِی پِچھوڑے (ٹَپ)ز مِن دِی دو-سه تَرکِیب مِن خَرِید کِی جَاتی ہَے، اوَ سِلرز کو ٹوکنز اِسے اُن کی بَلَنس مِن سِراہا جَاتے ہَیں۔',
    storesB1Desc: 'کسی بھی خالق یا کاروبار اپنا ایک دکاں (ستور) بناسکے، اپنا ایک پیج، برینڈنگ اور پروڈکٹس کی لسٹنگس لگا سکے۔',
