    aiSuiteDesc: 'دہوب (DeHub) میں خالقوں کے لیے ایک مکمل سیٹ آف ای آئی ٹولز شامل ہیں، جو اپ میں ہی دستیاب ہیں، کوئی بیرونی اکاؤنٹس یا ای پی آئی کیز کی ضرورت نہیں۔ یہ سیٹ میں ایک کنسالیشنل ایسسٹنٹ، اتھونومس ایجنٹس اور ایک نو-کڈ اپ بیلڈر شامل ہے، جس سے آپ ایک ایڈیا سے جنریٹڈ کنٹینٹ یا ایک کام کرتی مینی-اپ تک پہنچ سکتے ہیں، پلتفرم چھوڑے بغیر۔',
    aiSuiteB1Desc: 'ایک چٹ چال اسسٹنٹ جو دےہب کے بارے میں سوالات کا جواب دیتا ہے، پوسٹرز اور مارکیٹنگ کی مواد تیار کرتا ہے اور آپ کو کانتینٹ کی پلاننگ اور بنانے میں مدد دیتا ہے۔',
