    accountsDesc: 'دےہب میں داخلہ کے کئی طریقے ہیں اور ان میں سے کوئی بھی آپ کو پہلے سے ایک ولٹ رکھنے کی ضرورت نہیں رکھتا۔ گوگل، اپل یا ٹیلیگرام کے ذریعے سائن ان کریں، ای میل پر بھیجی گئی کوڈ کے ذریعے یا ایس ایم ایس کے ذریعے، فون یا کمپیوٹر پر پاسکی کے ذریعے، یا آپ جو ولٹ استعمال کر رہے ہیں اس کو کنیکٹ کر کے۔ سب کچھ ولٹ روٹ کے علاوہ آپ کے لیے ایک غیر ذخیرہ والا ولٹ بناتا ہے۔ آپ کی کلیدیں آپ کے پاس رہیں گی، ہم کبھی بھی ان کی دیکھ بھال نہیں کریں گے اور گیس سپانسر کی جاتی ہے تاکہ آپ ٹوکن خریدنے کے بغیر پوسٹ، ٹپ اور کولیکٹ کر سکیں۔ آپ کو صرف اس وقت اس ولٹ کو محفوظ رکھنے کا مطالبہ کیا جاتا ہے جب آپ اسے پہلی بار استعمال کرتے ہیں، سائن اپ کے وقت نہیں۔',
