    themesTitle: 'تھیمز تے اپیئرنس',
    themesDesc: 'DeHub سولہ اپیئرنس آپشنز پیش کریندے، نہ کہ صرف لائٹ-اینڈ-ڈارک ٹوگل: System, System Light, Immersive, Minimal, Minimal Light, Cosmic, Hazy, Swarms, Lava Lamp, Winter, War, Osaka, Jungle, Island, Hacker تے Horror۔ ہر ہک ہک مکمل سکن اے — ایندی اپݨی پیلیٹ، کروم، آئیکونوگرافی تے، انہاں وچوں کئی ہک کیتے، GPU تے رینڈر تھیوݨ آلا لائیو اینیمیٹڈ بیک گراؤنڈ۔ System مکمل طور تے عمیق (immersive) اے، جیندے وچ فل-وڈتھ پوسٹس بکس دی بجائے ہیئر لائنز نال ونڈیاں ہوئیاں ہن، تے System Light سفید کاغذ تے کالے سیاہی آلا سیم لے آؤٹ اے۔ Island ہک جھیل اے جیندے وچ عکاسی کرݨ آلا پاݨی اے جیہڑا تہاݙی مقامی گھڑی دے مطابق گولڈن آور توں رات تائیں بدلدا رہندے، Hacker ہولی ہولی تھیندی سبز بارش اے جیندے وچ ایپ مونو اسپیس وچ اے، تے Horror ہک پرانی VHS ٹیپ تے ملݨ آلی فاؤنڈ فوٹیج اے۔ سیٹنگز → اپیئرنس وچ ہک منتخب کرو، جتھاں ہر ہک دا نمونہ ݙکھایا ویندے؛ انہاں وچوں چار تہاکوں اپݨا ایکسنٹ کلر سیٹ کرݨ دی وی اجازت ݙیندن، تے Jungle دا اپݨا ڈے تے ایوننگ سوئچ اے۔',
