    preventFraudDesc1: 'بٹنگ کم پرنفٹل ہو جاتی ہے جب سرگرمی چین پر ٹریک کی جا سکتی ہے، بدمعاش افراد کو آسان طور پر جوڑ کر آخر کار تمام کاربران کی فہرست تیار کر لی جاتی ہے۔ اعلانات دیے جانے والے اعلیٰ درجے کے کاربران کو ٹارگٹ کرتے ہیں، جس سے نیچے کی لےئر میں کمزور استخراج شدہ قیمتیں چھوڑ دی جاتی ہیں، جہاں کوئی بھی باقی رہ جانے والا دھوکا باقی رہتا ہے۔ اس کے علاوہ، ہمارے دے سینٹرلائزڈ میڈریشن سے غیر قانونی سرگرمیوں کی تشخیص اور روکنے میں زیادہ کارآمدی ہوتی ہے۔',
    problemDesc2: '، 2028 تئیں 170 بلین ڈالر تئیں ودھن دا امکان اے۔ فراڈ کرنے والے اشتہاری اخراجات چوری کرن لئی جدید بوٹس تے حربے استعمال کردے نیں، جیہدے نال میٹرکس تے ROI متاثر ہوندے نیں، تے ڈیجیٹل اخراجات دا تقریباً 20-30% اکثر جعلی ٹریفک تے ضائع ہوندا اے۔',
