    a17: 'آپ ہمارے مرکزی پلیٹ فارم کے ذریعے DeHub کے d\'Apps تک رسائی حاصل کر سکتے ہیں ۔ DeHub ٹوکن ہولڈرز کو موجودہ اور مستقبل کی تمام ایپس میں بہتر خصوصیات اور فعالیت ملتی ہے ۔',
    a18: 'ہمارے روڈ میپ میں ڈی ایپ ایکو سسٹم کو بڑھانا، نئے گیمز لانچ کرنا، ڈی پن انفراسٹرکچر کو بڑھانا، AI ٹول کٹس تیار کرنا، اور پلیٹ فارم پر وسیع پیمانے پر گورننس رول آؤٹ جاری رکھنا شامل ہے ۔',
    a19: 'آپ تکنیکی مسائل کے لیے ہمارے آفیشل چینلز: tech@dehub.net کے ذریعے ہم سے رابطہ کر سکتے ہیں، یا اپ ڈیٹس اور کمیونٹی کی مصروفیت کے لیے ہمیں Twitter اور Instagram @ dehub_official پر فالو کر سکتے ہیں ۔',
    a22: 'نہیں۔ آپ Google، Apple یا Telegram کے ساتھ، اپنے ای میل ایڈریس یا SMS پر بھیجے گئے کوڈ کے ساتھ، یا پاس کی (passkey) کے ساتھ سائن ان کر سکتے ہیں، اور پس منظر میں آپ کے لیے ایک نان کسٹوڈیل والٹ بنایا جاتا ہے — چابیاں آپ کے پاس رہتی ہیں اور ہم کبھی تحویل نہیں لیتے۔ اگر آپ کے پاس پہلے سے والٹ ہے تو آپ اسے کنیکٹ کر سکتے ہیں یا اس کی چابیاں امپورٹ کر سکتے ہیں۔ والٹ پر مبنی نہ ہونے والے سائن انز کی گیس فیس بھی اسپانسر کی جاتی ہے، لہذا آپ مقامی ٹوکن خریدے بغیر پوسٹ، ٹپ اور کلیکٹ کر سکتے ہیں۔',
    a25: 'ایک بیج آپ کے پلیٹ فارم کی فیس کو 0.69% فی درجہ کم کرتا ہے، آپ کے مفت یومیہ پوسٹنگ الاؤنس میں اضافہ کرتا ہے اور اس سے آگے کسی بھی چیز پر چھوٹ دیتا ہے، DeHub ٹوکن خریدتے وقت آپ کو وہی 5% -30% کی رعایت دیتا ہے، سپر پاورز اور پروفائل کاسمیٹکس کو ان لاک کرتا ہے، اور آپ کے خیالات اور رد عمل کو مزید شمار کرتا ہے ۔ تیرہ درجوں کی قیمت ایک مقررہ تعداد میں ٹوکنز کے بجائے ڈالر میں ہوتی ہے، اور ایک بار جب آپ نے ایک درجہ حاصل کر لیا تو قیمت اسے آپ سے واپس نہیں لے سکتی ۔',
    a27: 'DeHub میں بنائے گئے لائیو آڈیو رومز ۔ ایک میزبان ایک کمرہ کھولتا ہے اور مقررین کو اسٹیج پر لاتا ہے، سامعین اسٹیج کے صفحے یا مشترکہ لنک سے آتے ہیں، اور پروڈکشن لیئر ایک DJ ساؤنڈ بورڈ، صوتی اثرات، ریڈیو اسٹیشن، اسکرین شیئر اور براؤزر گو لائیو شامل کرتی ہے جس میں OBS کی ضرورت نہیں ہوتی ہے ۔ کمروں میں لائیو سب ٹائٹلز ہوتے ہیں جن کا ترجمہ ہر سننے والا جو بھی زبان میں پڑھتا ہے، میزبان کی اپنی کلون کی آواز میں بلند آواز سے ڈب کیا جا سکتا ہے، اور اس کے بعد قابل تلاش ری پلے کے لیے ہر اسٹیج ریکارڈ کیا جا سکتا ہے ۔',
    a29: 'تخلیق کار اسے تحریر کرتے وقت ایک پختہ پوسٹ کو نشان زد کرتے ہیں، اور وہ پوسٹس عوامی ہوم فیڈ سے دور رہتی ہیں اور تلاش سے باہر رہتی ہیں جب تک کہ آپ ترتیبات میں "پختہ مواد دکھائیں" کو آن نہیں کرتے ہیں ۔ آپ کسی بھی پوسٹ پر \'مینو سے کسی مصنف کو خاموش یا بلاک کر سکتے ہیں، فی زمرہ منتخب کر سکتے ہیں جو اطلاعات آپ تک پہنچتی ہیں، اور بچوں کے موڈ کو آن کر سکتے ہیں، جو ایک PIN کے ذریعے محفوظ ہے، لہذا ایک آلہ صرف بچوں کے لیے بنائی گئی پوسٹس دکھاتا ہے ۔',
    a3: 'تجاویز گورننس (Governance) کے صفحے سے پیش کی جاتی ہیں اور ان پر ووٹنگ ہوتی ہے۔ تجویز شروع کرنے کی فیس 10,000 DeHub ٹوکن ہے، جس کی تصدیق آن چین ہوتی ہے، جو بورڈ کو اسپام سے پاک رکھتی ہے۔ ووٹنگ خود مفت ہے اور آپ کے اسٹیکنگ بیج کے لحاظ سے اس کا وزن (weight) طے ہوتا ہے۔ ایک ووٹ سات دن تک جاری رہتا ہے، اور کوئی تجویز صرف اسی صورت میں بھاری اکثریت سے منظور ہوتی ہے اگر کم از کم دس مختلف والٹس نے اس میں حصہ لیا ہو، تاکہ کوئی بھی بڑا ہولڈر اکیلے کچھ منظور نہ کروا سکے۔',
