    a20: 'نہیں، ڈیہب ٹوکنز صرف ڈیہب اکوسسٹم میں استعمال کے لیے ہیں، جیسے گیم یا اپ میں ڈیجٹل کرنسی کی طرح۔ یہ سرمایہ کاری کے ادارے نہیں ہیں اور مارکیٹات بہت زیادہ ناپیدار ہیں۔',
    a21: 'DeHub نھاں ایک دھنچلہ (دِسِنتَرلائزڈ) کَنتِنت مَڈیرَیشن سِسٹم اِستِمال کرتی ہے، جِس میں سَامعہی مِمبرز دِسپُوٹ مَنجمنٹ اور کَنتِنت مَڈیرَیشن میں شَمِل ہو کر انعامات پَائیں گے، جبکہ پِلَٹفرم کی کِفایتِ نِظَام کو برقرار رکھیں گے۔',
    a23: 'ہاں، روزانہ کی ایک حد تک جو آپ کی اسٹیکنگ بڈز کے ساتھ بڑھتی جاتی ہے۔ ہر اکاؤنٹ کو روزانہ دس ٹیکسٹ پوسٹس اور ایک گیگا بیٹ وڈیو، تصاویر اور آڈیو مفت ملتی ہے، اور دونوں پولز میڈنائٹ یوٹیسی کے وقت ریسٹ ہو جاتے ہیں۔ اس سے آگے، وہ دن کی بقیہ چیزوں کا قیمتیں ڈیہاب ٹوکنز میں ہوتی ہے — تقریبا ایک سینٹ پر ایک ٹیکسٹ پوسٹ اور دو ڈالر پر ایک گیگا بیٹ، جو پرو-راتا چارج کی جاتی ہے اور صرف وہ حصہ جو حد سے آگے چلا جاتا ہے۔ ریپوسٹس، کامینٹس، رییکشنز، ٹپس اور میسجز کبھی بھی اس میں شامل نہیں ہوتے۔',
